import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { verifyCodeHandler } from "../handlers/verifyCodeHandler";
import type { ApiError } from "../runtime/client";
import type { VerifyCodeRequest } from "../types/VerifyCodeRequest";

type Data = Awaited<ReturnType<typeof verifyCodeHandler>>;
type Vars = VerifyCodeRequest;

export function useVerifyCode(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => verifyCodeHandler(vars),
    ...options,
  });
}
